FILES = {
    "memeflow-3d/layout.js": "\nexport const NODES = [\n  { id: 'discovery', label: 'DISCOVERY', color: 0x315cff, pos: [-3.20, 0, -3.18], size: [2.20, 1.50] },\n  { id: 'bootstrap', label: 'FAST BOOTSTRAP', color: 0x315cff, pos: [0, 0, -3.18], size: [2.36, 1.50] },\n  { id: 'core', label: 'MEMEFLOW CORE', color: 0x56e79a, pos: [3.20, 0, -3.18], size: [2.90, 1.88], core: true },\n\n  { id: 'risk', label: 'RISK ENGINE', color: 0x43c8ee, pos: [-3.20, 0, -0.34], size: [2.20, 1.50] },\n  { id: 'market', label: 'MARKET LEDGER', color: 0x3a7dff, pos: [0, 0, -0.34], size: [2.26, 1.50] },\n  { id: 'holders', label: 'HOLDER LEDGER', color: 0x43c8ee, pos: [3.20, 0, -0.34], size: [2.20, 1.50] },\n\n  { id: 'openai', label: 'OPENAI ASSISTANT', color: 0x43c8ee, pos: [-3.20, 0, 2.50], size: [2.34, 1.50] },\n  { id: 'decision', label: 'DECISION', color: 0x8d58ff, pos: [0, 0, 2.50], size: [2.12, 1.50], decision: true },\n  { id: 'paper', label: 'PAPER ENGINE', color: 0x315cff, pos: [3.20, 0, 2.50], size: [2.20, 1.50] },\n\n  { id: 'execution', label: 'LIVE EXECUTION', color: 0x48df8b, pos: [0, 0, 5.18], size: [2.36, 1.50], execution: true }\n];\n\nexport const ROUTES = [\n  ['discovery', 'bootstrap', 0x74dcff],\n  ['bootstrap', 'core', 0x74dcff],\n\n  ['core', 'risk', 0x6cdfff],\n  ['core', 'market', 0x59e99c],\n  ['core', 'holders', 0x59e99c],\n\n  ['risk', 'market', 0x74dcff],\n  ['market', 'holders', 0x74dcff],\n\n  ['risk', 'openai', 0x9a70ff],\n  ['openai', 'decision', 0x74dcff],\n  ['market', 'decision', 0x74dcff],\n\n  ['decision', 'paper', 0xa977ff],\n  ['paper', 'execution', 0x61eda0]\n];\n",
    "memeflow-3d/assets.js": "\nimport { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';\n\nconst loader = new GLTFLoader();\n\nfunction loadGLB(url) {\n  return new Promise((resolve, reject) => {\n    loader.load(\n      url,\n      gltf => resolve(gltf.scene),\n      undefined,\n      reject\n    );\n  });\n}\n\nexport async function loadHardwareAssets() {\n  const [standard, core, terminal] = await Promise.all([\n    loadGLB('/memeflow-3d/assets/module-standard.glb?v=true-3d-glb-v5'),\n    loadGLB('/memeflow-3d/assets/module-core.glb?v=true-3d-glb-v5'),\n    loadGLB('/memeflow-3d/assets/module-terminal.glb?v=true-3d-glb-v5')\n  ]);\n\n  return {\n    standard,\n    core,\n    terminal\n  };\n}\n\nexport function cloneHardwareAsset(assets, node) {\n  const source =\n    node.core\n      ? assets.core\n      : node.decision || node.execution\n        ? assets.terminal\n        : assets.standard;\n\n  return source.clone(true);\n}\n",
    "memeflow-3d/materials.js": "\nimport * as THREE from 'three';\n\nfunction hex(color) {\n  return '#' + Number(color).toString(16).padStart(6, '0');\n}\n\nfunction radialTexture(size = 256) {\n  const canvas = document.createElement('canvas');\n  canvas.width = size;\n  canvas.height = size;\n\n  const ctx = canvas.getContext('2d');\n\n  const gradient = ctx.createRadialGradient(\n    size / 2,\n    size / 2,\n    4,\n    size / 2,\n    size / 2,\n    size * 0.48\n  );\n\n  gradient.addColorStop(0.00, 'rgba(255,255,255,.92)');\n  gradient.addColorStop(0.16, 'rgba(255,255,255,.42)');\n  gradient.addColorStop(0.48, 'rgba(255,255,255,.10)');\n  gradient.addColorStop(1.00, 'rgba(255,255,255,0)');\n\n  ctx.fillStyle = gradient;\n  ctx.fillRect(0, 0, size, size);\n\n  const texture = new THREE.CanvasTexture(canvas);\n  texture.colorSpace = THREE.SRGBColorSpace;\n\n  return texture;\n}\n\nexport const SOFT_GLOW = radialTexture();\n\nexport function chassisMaterial(color, tier = 0, emphasis = 1) {\n  const top = tier === 2;\n\n  return new THREE.MeshPhysicalMaterial({\n    color:\n      top\n        ? 0x06121a\n        : tier === 1\n          ? 0x03090e\n          : 0x010508,\n\n    emissive: color,\n\n    emissiveIntensity:\n      (top ? 0.045 : tier === 1 ? 0.018 : 0.007)\n      * emphasis,\n\n    metalness: top ? 0.64 : 0.78,\n    roughness: top ? 0.18 : 0.26,\n\n    clearcoat: 1,\n    clearcoatRoughness: 0.045\n  });\n}\n\nexport function glassMaterial(color, emphasis = 1) {\n  return new THREE.MeshPhysicalMaterial({\n    color: 0x06131b,\n    emissive: color,\n    emissiveIntensity: 0.095 * emphasis,\n\n    metalness: 0.10,\n    roughness: 0.08,\n\n    transmission: 0.26,\n    thickness: 0.24,\n    ior: 1.32,\n\n    clearcoat: 1,\n    clearcoatRoughness: 0.02,\n\n    transparent: true,\n    opacity: 0.74\n  });\n}\n\nexport function metalDetailMaterial(color, emphasis = 1) {\n  return new THREE.MeshStandardMaterial({\n    color: 0x0a141a,\n    emissive: color,\n    emissiveIntensity: 0.045 * emphasis,\n    metalness: 0.90,\n    roughness: 0.19\n  });\n}\n\nexport function silverMaterial(color) {\n  return new THREE.MeshStandardMaterial({\n    color: 0x8da1ad,\n    emissive: color,\n    emissiveIntensity: 0.035,\n    metalness: 0.96,\n    roughness: 0.16\n  });\n}\n\nexport function edgeMaterial(color, opacity = 0.55) {\n  return new THREE.LineBasicMaterial({\n    color,\n    transparent: true,\n    opacity,\n    depthWrite: false,\n    blending: THREE.AdditiveBlending\n  });\n}\n\nexport function glowPlane(width, depth, color, opacity = 0.10) {\n  const plane = new THREE.Mesh(\n    new THREE.PlaneGeometry(width, depth),\n    new THREE.MeshBasicMaterial({\n      map: SOFT_GLOW,\n      color,\n      transparent: true,\n      opacity,\n      depthWrite: false,\n      blending: THREE.AdditiveBlending,\n      side: THREE.DoubleSide\n    })\n  );\n\n  plane.rotation.x = -Math.PI / 2;\n  return plane;\n}\n\nexport function labelTexture(text, color) {\n  const canvas = document.createElement('canvas');\n\n  canvas.width = 1024;\n  canvas.height = 210;\n\n  const ctx = canvas.getContext('2d');\n  const accent = hex(color);\n\n  const bg = ctx.createLinearGradient(0, 0, 0, canvas.height);\n  bg.addColorStop(0, 'rgba(5,10,14,.96)');\n  bg.addColorStop(1, 'rgba(1,4,6,.99)');\n\n  ctx.fillStyle = bg;\n  ctx.fillRect(0, 0, canvas.width, canvas.height);\n\n  ctx.strokeStyle = accent;\n  ctx.globalAlpha = 0.42;\n  ctx.lineWidth = 3;\n  ctx.strokeRect(7, 7, canvas.width - 14, canvas.height - 14);\n  ctx.globalAlpha = 1;\n\n  ctx.fillStyle = '#eef5f8';\n  ctx.textAlign = 'center';\n  ctx.textBaseline = 'middle';\n\n  ctx.shadowColor = accent;\n  ctx.shadowBlur = 9;\n\n  const fontSize =\n    text.length > 15\n      ? 58\n      : text.length > 11\n        ? 66\n        : 76;\n\n  ctx.font = `800 ${fontSize}px Arial, sans-serif`;\n  ctx.fillText(text, canvas.width / 2, canvas.height / 2);\n\n  ctx.shadowBlur = 0;\n\n  const texture = new THREE.CanvasTexture(canvas);\n  texture.colorSpace = THREE.SRGBColorSpace;\n\n  return texture;\n}\n\nexport function iconTexture(kind, color) {\n  const canvas = document.createElement('canvas');\n\n  canvas.width = 512;\n  canvas.height = 512;\n\n  const ctx = canvas.getContext('2d');\n  const accent = hex(color);\n\n  ctx.translate(256, 256);\n\n  ctx.strokeStyle = accent;\n  ctx.fillStyle = accent;\n  ctx.lineWidth = 11;\n  ctx.lineCap = 'round';\n  ctx.lineJoin = 'round';\n\n  ctx.shadowColor = accent;\n  ctx.shadowBlur = 18;\n\n  ctx.globalAlpha = 0.20;\n  ctx.beginPath();\n  ctx.arc(0, 0, 132, 0, Math.PI * 2);\n  ctx.stroke();\n\n  ctx.globalAlpha = 0.62;\n  ctx.beginPath();\n  ctx.arc(0, 0, 92, 0, Math.PI * 2);\n  ctx.stroke();\n\n  ctx.globalAlpha = 1;\n\n  if (kind === 'discovery') {\n    ctx.beginPath();\n    ctx.arc(-22, -20, 45, 0, Math.PI * 2);\n    ctx.stroke();\n\n    ctx.beginPath();\n    ctx.moveTo(10, 14);\n    ctx.lineTo(70, 76);\n    ctx.stroke();\n  }\n\n  else if (kind === 'bootstrap') {\n    ctx.beginPath();\n    ctx.moveTo(18, -92);\n    ctx.lineTo(-44, 4);\n    ctx.lineTo(3, 4);\n    ctx.lineTo(-18, 88);\n    ctx.lineTo(62, -18);\n    ctx.lineTo(10, -18);\n    ctx.closePath();\n    ctx.stroke();\n  }\n\n  else if (kind === 'core') {\n    for (const radius of [34, 70, 112]) {\n      ctx.beginPath();\n      ctx.arc(0, 0, radius, 0, Math.PI * 2);\n      ctx.stroke();\n    }\n\n    ctx.beginPath();\n    ctx.arc(0, 0, 13, 0, Math.PI * 2);\n    ctx.fill();\n  }\n\n  else if (kind === 'risk') {\n    ctx.beginPath();\n    ctx.moveTo(0, -88);\n    ctx.lineTo(72, -52);\n    ctx.lineTo(56, 35);\n    ctx.quadraticCurveTo(0, 94, -56, 35);\n    ctx.lineTo(-72, -52);\n    ctx.closePath();\n    ctx.stroke();\n  }\n\n  else if (kind === 'market') {\n    ctx.beginPath();\n    ctx.moveTo(-82, 52);\n    ctx.lineTo(-28, 9);\n    ctx.lineTo(8, 31);\n    ctx.lineTo(76, -64);\n    ctx.stroke();\n\n    ctx.beginPath();\n    ctx.moveTo(76, -64);\n    ctx.lineTo(72, -9);\n    ctx.moveTo(76, -64);\n    ctx.lineTo(22, -58);\n    ctx.stroke();\n  }\n\n  else if (kind === 'holders') {\n    const points = [\n      [0, -70],\n      [-64, 40],\n      [64, 40]\n    ];\n\n    for (const [x, y] of points) {\n      ctx.beginPath();\n      ctx.arc(x, y, 21, 0, Math.PI * 2);\n      ctx.stroke();\n    }\n\n    ctx.beginPath();\n    ctx.moveTo(0, -48);\n    ctx.lineTo(-46, 24);\n    ctx.moveTo(0, -48);\n    ctx.lineTo(46, 24);\n    ctx.moveTo(-42, 40);\n    ctx.lineTo(42, 40);\n    ctx.stroke();\n  }\n\n  else if (kind === 'openai') {\n    for (let i = 0; i < 6; i++) {\n      ctx.save();\n      ctx.rotate(i * Math.PI / 3);\n      ctx.beginPath();\n      ctx.ellipse(0, -48, 31, 60, 0, 0, Math.PI * 2);\n      ctx.stroke();\n      ctx.restore();\n    }\n  }\n\n  else if (kind === 'decision') {\n    ctx.beginPath();\n    ctx.arc(0, 0, 72, 0, Math.PI * 2);\n    ctx.stroke();\n\n    ctx.beginPath();\n    ctx.moveTo(-12, -50);\n    ctx.lineTo(18, -18);\n    ctx.lineTo(-8, 12);\n    ctx.lineTo(27, 54);\n    ctx.stroke();\n  }\n\n  else if (kind === 'paper') {\n    ctx.strokeRect(-60, -84, 120, 168);\n\n    for (const y of [-40, 0, 40]) {\n      ctx.beginPath();\n      ctx.moveTo(-32, y);\n      ctx.lineTo(32, y);\n      ctx.stroke();\n    }\n  }\n\n  else if (kind === 'execution') {\n    ctx.beginPath();\n    ctx.arc(0, 0, 78, 0, Math.PI * 2);\n    ctx.stroke();\n\n    ctx.beginPath();\n    ctx.arc(0, 0, 22, 0, Math.PI * 2);\n    ctx.fill();\n\n    ctx.beginPath();\n    ctx.moveTo(0, -112);\n    ctx.lineTo(0, -78);\n    ctx.moveTo(0, 78);\n    ctx.lineTo(0, 112);\n    ctx.moveTo(-112, 0);\n    ctx.lineTo(-78, 0);\n    ctx.moveTo(78, 0);\n    ctx.lineTo(112, 0);\n    ctx.stroke();\n  }\n\n  ctx.shadowBlur = 0;\n\n  const texture = new THREE.CanvasTexture(canvas);\n  texture.colorSpace = THREE.SRGBColorSpace;\n\n  return texture;\n}\n",
    "memeflow-3d/modules.js": "\nimport * as THREE from 'three';\n\nimport {\n  cloneHardwareAsset\n} from './assets.js?v=true-3d-glb-v5';\n\nimport {\n  chassisMaterial,\n  glassMaterial,\n  metalDetailMaterial,\n  silverMaterial,\n  glowPlane,\n  labelTexture,\n  iconTexture\n} from './materials.js?v=true-3d-glb-v5';\n\nconst BASE_SIZE = {\n  standard: [2.2, 1.5],\n  core: [2.8, 1.8],\n  terminal: [2.3, 1.5]\n};\n\nfunction variantFor(node) {\n  if (node.core) return 'core';\n  if (node.decision || node.execution) return 'terminal';\n  return 'standard';\n}\n\nfunction styleHardware(root, node, emphasis) {\n  root.traverse(object => {\n    if (!object.isMesh) return;\n\n    const name = (object.name || '').toLowerCase();\n\n    if (name.includes('base')) {\n      object.material = chassisMaterial(node.color, 0, emphasis);\n    }\n\n    else if (name.includes('mid')) {\n      object.material = chassisMaterial(node.color, 1, emphasis);\n    }\n\n    else if (name.includes('top')) {\n      object.material = chassisMaterial(node.color, 2, emphasis);\n    }\n\n    else if (\n      name.includes('glass')\n      || name.includes('inset')\n    ) {\n      object.material = glassMaterial(node.color, emphasis);\n    }\n\n    else if (name.includes('post')) {\n      object.material = silverMaterial(node.color);\n    }\n\n    else {\n      object.material = metalDetailMaterial(node.color, emphasis);\n    }\n\n    object.castShadow = false;\n    object.receiveShadow = false;\n  });\n}\n\nfunction makeLed(color, active) {\n  return new THREE.Mesh(\n    new THREE.SphereGeometry(0.028, 10, 8),\n    new THREE.MeshBasicMaterial({\n      color,\n      transparent: true,\n      opacity: active ? 1 : 0.46,\n      depthWrite: false,\n      blending: THREE.AdditiveBlending\n    })\n  );\n}\n\nexport function createModule(node, assets) {\n  const group = new THREE.Group();\n\n  group.name = `MEMEFLOW_NODE_${node.id}`;\n\n  group.position.set(\n    node.pos[0],\n    0,\n    node.pos[2]\n  );\n\n  const hardware = new THREE.Group();\n  group.add(hardware);\n\n  const emphasis =\n    node.core\n      ? 1.55\n      : node.decision\n        ? 1.26\n        : node.execution\n          ? 1.32\n          : 1;\n\n  const variant = variantFor(node);\n  const sourceSize = BASE_SIZE[variant];\n\n  const chassis = cloneHardwareAsset(\n    assets,\n    node\n  );\n\n  chassis.name = `GLB_CHASSIS_${node.id}`;\n\n  chassis.scale.set(\n    node.size[0] / sourceSize[0],\n    1,\n    node.size[1] / sourceSize[1]\n  );\n\n  styleHardware(\n    chassis,\n    node,\n    emphasis\n  );\n\n  hardware.add(chassis);\n\n  const fitObject = chassis;\n\n  const width = node.size[0];\n  const depth = node.size[1];\n\n  const icon = new THREE.Mesh(\n    new THREE.PlaneGeometry(\n      width * 0.58,\n      depth * 0.50\n    ),\n    new THREE.MeshBasicMaterial({\n      map: iconTexture(\n        node.id,\n        node.color\n      ),\n      transparent: true,\n      opacity: node.core ? 0.96 : 0.78,\n      depthWrite: false,\n      blending: THREE.AdditiveBlending\n    })\n  );\n\n  icon.rotation.x = -Math.PI / 2;\n  icon.position.y = 0.125;\n\n  hardware.add(icon);\n\n  const label = new THREE.Mesh(\n    new THREE.PlaneGeometry(\n      width * 0.72,\n      node.core ? 0.30 : 0.27\n    ),\n    new THREE.MeshBasicMaterial({\n      map: labelTexture(\n        node.label,\n        node.color\n      ),\n      transparent: true,\n      opacity: 0.98,\n      depthWrite: false\n    })\n  );\n\n  label.position.set(\n    0,\n    -0.13,\n    depth * 0.545\n  );\n\n  hardware.add(label);\n\n  const leds = [];\n\n  for (let index = 0; index < 3; index++) {\n    const led = makeLed(\n      index === 2\n        ? node.color\n        : index === 1\n          ? 0x426d82\n          : 0x233d4a,\n      index === 2\n    );\n\n    led.position.set(\n      width * 0.22 + index * 0.095,\n      -0.07,\n      depth * 0.555\n    );\n\n    hardware.add(led);\n    leds.push(led);\n  }\n\n  const outerGlow = glowPlane(\n    width * 1.32,\n    depth * 1.38,\n    node.color,\n    node.core\n      ? 0.12\n      : node.decision\n        ? 0.070\n        : node.execution\n          ? 0.080\n          : 0.026\n  );\n\n  outerGlow.position.y = -0.48;\n  hardware.add(outerGlow);\n\n  const innerGlow = glowPlane(\n    width * 0.94,\n    depth * 0.98,\n    node.color,\n    node.core ? 0.075 : 0.020\n  );\n\n  innerGlow.position.y = -0.455;\n  hardware.add(innerGlow);\n\n  let rings = null;\n\n  if (node.core) {\n    rings = new THREE.Group();\n    rings.position.y = 0.145;\n\n    for (const [radius, tube, opacity] of [\n      [0.42, 0.012, 0.72],\n      [0.68, 0.009, 0.40],\n      [0.94, 0.007, 0.16]\n    ]) {\n      const ring = new THREE.Mesh(\n        new THREE.TorusGeometry(\n          radius,\n          tube,\n          10,\n          64\n        ),\n        new THREE.MeshBasicMaterial({\n          color: node.color,\n          transparent: true,\n          opacity,\n          depthWrite: false,\n          blending: THREE.AdditiveBlending\n        })\n      );\n\n      ring.rotation.x = Math.PI / 2;\n      rings.add(ring);\n    }\n\n    hardware.add(rings);\n  }\n\n  const pickMesh = new THREE.Mesh(\n    new THREE.BoxGeometry(\n      width,\n      0.54,\n      depth\n    ),\n    new THREE.MeshBasicMaterial({\n      transparent: true,\n      opacity: 0,\n      depthWrite: false\n    })\n  );\n\n  pickMesh.position.y = -0.10;\n  pickMesh.userData.nodeId = node.id;\n\n  hardware.add(pickMesh);\n\n  return {\n    id: node.id,\n    node,\n    group,\n    hardware,\n    fitObject,\n    chassis,\n    label,\n    icon,\n    outerGlow,\n    innerGlow,\n    leds,\n    rings,\n    pickMesh\n  };\n}\n",
    "memeflow-3d/routes.js": "\nimport * as THREE from 'three';\n\nfunction routePoint(nodePos) {\n  return new THREE.Vector3(\n    nodePos[0],\n    -0.22,\n    nodePos[2]\n  );\n}\n\nfunction routeCurve(from, to) {\n  const a = routePoint(from);\n  const b = routePoint(to);\n\n  const dx = Math.abs(b.x - a.x);\n  const dz = Math.abs(b.z - a.z);\n\n  const points = [a];\n\n  if (dx < 0.15 || dz < 0.15) {\n    points.push(\n      a.clone().lerp(b, 0.5)\n    );\n  }\n\n  else if (dx >= dz) {\n    const mx =\n      a.x\n      + (b.x - a.x) * 0.52;\n\n    points.push(\n      new THREE.Vector3(\n        mx,\n        -0.22,\n        a.z\n      ),\n      new THREE.Vector3(\n        mx,\n        -0.22,\n        b.z\n      )\n    );\n  }\n\n  else {\n    const mz =\n      a.z\n      + (b.z - a.z) * 0.50;\n\n    points.push(\n      new THREE.Vector3(\n        a.x,\n        -0.22,\n        mz\n      ),\n      new THREE.Vector3(\n        b.x,\n        -0.22,\n        mz\n      )\n    );\n  }\n\n  points.push(b);\n\n  return new THREE.CatmullRomCurve3(\n    points,\n    false,\n    'catmullrom',\n    0.022\n  );\n}\n\nfunction additive(color, opacity) {\n  return new THREE.MeshBasicMaterial({\n    color,\n    transparent: true,\n    opacity,\n    depthWrite: false,\n    blending: THREE.AdditiveBlending\n  });\n}\n\nfunction port(color, point) {\n  const group = new THREE.Group();\n\n  const outer = new THREE.Mesh(\n    new THREE.CylinderGeometry(\n      0.075,\n      0.075,\n      0.028,\n      18\n    ),\n    new THREE.MeshStandardMaterial({\n      color: 0x08131a,\n      emissive: color,\n      emissiveIntensity: 0.26,\n      metalness: 0.86,\n      roughness: 0.18\n    })\n  );\n\n  outer.position.copy(point);\n  outer.position.y = -0.18;\n\n  group.add(outer);\n\n  const light = new THREE.Mesh(\n    new THREE.SphereGeometry(\n      0.030,\n      10,\n      8\n    ),\n    additive(color, 0.86)\n  );\n\n  light.position.copy(point);\n  light.position.y = -0.145;\n\n  group.add(light);\n\n  return group;\n}\n\nexport function createRoute(from, to, color) {\n  const curve = routeCurve(from, to);\n\n  const group = new THREE.Group();\n\n  const outer = new THREE.Mesh(\n    new THREE.TubeGeometry(\n      curve,\n      84,\n      0.042,\n      8,\n      false\n    ),\n    additive(color, 0.040)\n  );\n\n  group.add(outer);\n\n  const rail = new THREE.Mesh(\n    new THREE.TubeGeometry(\n      curve,\n      84,\n      0.013,\n      8,\n      false\n    ),\n    additive(color, 0.42)\n  );\n\n  group.add(rail);\n\n  const coreLine = new THREE.Line(\n    new THREE.BufferGeometry()\n      .setFromPoints(\n        curve.getPoints(100)\n      ),\n    new THREE.LineBasicMaterial({\n      color,\n      transparent: true,\n      opacity: 0.67,\n      depthWrite: false,\n      blending: THREE.AdditiveBlending\n    })\n  );\n\n  group.add(coreLine);\n\n  group.add(\n    port(color, curve.getPointAt(0.015)),\n    port(color, curve.getPointAt(0.985))\n  );\n\n  const packets = [];\n\n  for (let index = 0; index < 3; index++) {\n    const packetGroup = new THREE.Group();\n\n    const core = new THREE.Mesh(\n      new THREE.SphereGeometry(\n        0.030,\n        10,\n        8\n      ),\n      additive(0xffffff, 0.92)\n    );\n\n    const halo = new THREE.Mesh(\n      new THREE.SphereGeometry(\n        0.065,\n        10,\n        8\n      ),\n      additive(color, 0.10)\n    );\n\n    packetGroup.add(core, halo);\n\n    packetGroup.userData.seed =\n      index / 3;\n\n    packetGroup.userData.speed =\n      0.040 + index * 0.003;\n\n    group.add(packetGroup);\n    packets.push(packetGroup);\n  }\n\n  return {\n    group,\n    curve,\n    packets,\n    color\n  };\n}\n\nexport function animateRoutes(routes, time) {\n  for (const route of routes) {\n    for (\n      let index = 0;\n      index < route.packets.length;\n      index++\n    ) {\n      const packet = route.packets[index];\n\n      const t =\n        (\n          packet.userData.seed\n          + time * packet.userData.speed\n        ) % 1;\n\n      packet.position.copy(\n        route.curve.getPointAt(t)\n      );\n\n      const pulse =\n        0.90\n        + Math.sin(\n          time * 6.8\n          + index * 1.8\n          + t * 9\n        ) * 0.12;\n\n      packet.scale.setScalar(pulse);\n    }\n  }\n}\n",
    "memeflow-3d/scene.js": "\nimport * as THREE from 'three';\n\nimport {\n  OrbitControls\n} from 'three/addons/controls/OrbitControls.js';\n\nimport {\n  EffectComposer\n} from 'three/addons/postprocessing/EffectComposer.js';\n\nimport {\n  RenderPass\n} from 'three/addons/postprocessing/RenderPass.js';\n\nimport {\n  UnrealBloomPass\n} from 'three/addons/postprocessing/UnrealBloomPass.js';\n\nimport {\n  OutputPass\n} from 'three/addons/postprocessing/OutputPass.js';\n\nimport {\n  NODES,\n  ROUTES\n} from './layout.js?v=true-3d-glb-v5';\n\nimport {\n  loadHardwareAssets\n} from './assets.js?v=true-3d-glb-v5';\n\nimport {\n  createModule\n} from './modules.js?v=true-3d-glb-v5';\n\nimport {\n  createRoute,\n  animateRoutes\n} from './routes.js?v=true-3d-glb-v5';\n\nfunction buildFitBounds(\n  scene,\n  modules\n) {\n  scene.updateMatrixWorld(true);\n\n  const box =\n    new THREE.Box3()\n      .makeEmpty();\n\n  for (\n    const module\n    of modules.values()\n  ) {\n    module.group\n      ?.updateWorldMatrix(\n        true,\n        true\n      );\n\n    module.fitObject\n      ?.updateWorldMatrix(\n        true,\n        true\n      );\n\n    if (module.fitObject) {\n      box.expandByObject(\n        module.fitObject,\n        true\n      );\n    }\n  }\n\n  const size =\n    new THREE.Vector3();\n\n  box.getSize(size);\n\n  if (\n    box.isEmpty()\n    || !Number.isFinite(size.x)\n    || !Number.isFinite(size.z)\n    || size.x < 6\n    || size.z < 7\n  ) {\n    box.makeEmpty();\n\n    for (\n      const module\n      of modules.values()\n    ) {\n      const node = module.node;\n\n      if (!node) continue;\n\n      const width =\n        Number(node.size?.[0])\n        || 2.2;\n\n      const depth =\n        Number(node.size?.[1])\n        || 1.5;\n\n      const x =\n        Number(node.pos?.[0])\n        || 0;\n\n      const z =\n        Number(node.pos?.[2])\n        || 0;\n\n      box.expandByPoint(\n        new THREE.Vector3(\n          x - width * 0.62,\n          -0.66,\n          z - depth * 0.65\n        )\n      );\n\n      box.expandByPoint(\n        new THREE.Vector3(\n          x + width * 0.62,\n          0.28,\n          z + depth * 0.65\n        )\n      );\n    }\n  }\n\n  return box;\n}\n\nfunction boxCorners(box) {\n  const min = box.min;\n  const max = box.max;\n\n  return [\n    new THREE.Vector3(min.x, min.y, min.z),\n    new THREE.Vector3(min.x, min.y, max.z),\n    new THREE.Vector3(min.x, max.y, min.z),\n    new THREE.Vector3(min.x, max.y, max.z),\n    new THREE.Vector3(max.x, min.y, min.z),\n    new THREE.Vector3(max.x, min.y, max.z),\n    new THREE.Vector3(max.x, max.y, min.z),\n    new THREE.Vector3(max.x, max.y, max.z)\n  ];\n}\n\nexport async function bootMemeflowTrue3D(\n  rootId = 'memeflowTrue3DHost'\n) {\n  const mount =\n    document.getElementById(rootId);\n\n  if (!mount) {\n    throw new Error(\n      'True 3D mount not found: '\n      + rootId\n    );\n  }\n\n  mount.replaceChildren();\n\n  const scene = new THREE.Scene();\n  scene.background = new THREE.Color(0x000000);\n\n  const camera =\n    new THREE.PerspectiveCamera(\n      41,\n      1,\n      0.05,\n      240\n    );\n\n  const renderer =\n    new THREE.WebGLRenderer({\n      antialias: true,\n      alpha: false,\n      powerPreference:\n        'high-performance'\n    });\n\n  renderer.setPixelRatio(\n    Math.min(\n      window.devicePixelRatio || 1,\n      1.75\n    )\n  );\n\n  renderer.outputColorSpace =\n    THREE.SRGBColorSpace;\n\n  renderer.toneMapping =\n    THREE.ACESFilmicToneMapping;\n\n  renderer.toneMappingExposure =\n    0.98;\n\n  renderer.domElement.id =\n    'memeflowTrue3DCanvas';\n\n  mount.appendChild(\n    renderer.domElement\n  );\n\n  const composer =\n    new EffectComposer(renderer);\n\n  composer.addPass(\n    new RenderPass(\n      scene,\n      camera\n    )\n  );\n\n  const bloom =\n    new UnrealBloomPass(\n      new THREE.Vector2(1, 1),\n      0.24,\n      0.34,\n      0.86\n    );\n\n  composer.addPass(bloom);\n  composer.addPass(\n    new OutputPass()\n  );\n\n  const controls =\n    new OrbitControls(\n      camera,\n      renderer.domElement\n    );\n\n  controls.enablePan = false;\n  controls.enableDamping = true;\n  controls.dampingFactor = 0.055;\n  controls.rotateSpeed = 0.54;\n  controls.zoomSpeed = 1.04;\n\n  controls.minAzimuthAngle = -Infinity;\n  controls.maxAzimuthAngle = Infinity;\n  controls.minPolarAngle = 0.10;\n  controls.maxPolarAngle = Math.PI - 0.10;\n\n  if (controls.touches) {\n    controls.touches.ONE =\n      THREE.TOUCH.ROTATE;\n\n    controls.touches.TWO =\n      THREE.TOUCH.DOLLY_ROTATE;\n  }\n\n  scene.add(\n    new THREE.HemisphereLight(\n      0x9ecfe8,\n      0x010203,\n      0.32\n    )\n  );\n\n  const key =\n    new THREE.DirectionalLight(\n      0xf3fbff,\n      1.10\n    );\n\n  key.position.set(\n    4.5,\n    9.0,\n    6.8\n  );\n\n  scene.add(key);\n\n  const cyanRim =\n    new THREE.PointLight(\n      0x58d7ff,\n      6.5,\n      21,\n      2\n    );\n\n  cyanRim.position.set(\n    -5.2,\n    3.2,\n    1.8\n  );\n\n  scene.add(cyanRim);\n\n  const greenCore =\n    new THREE.PointLight(\n      0x57e69a,\n      9.0,\n      18,\n      2\n    );\n\n  greenCore.position.set(\n    3.2,\n    2.8,\n    -3.1\n  );\n\n  scene.add(greenCore);\n\n  const violetDecision =\n    new THREE.PointLight(\n      0x8d58ff,\n      5.2,\n      15,\n      2\n    );\n\n  violetDecision.position.set(\n    0,\n    2.0,\n    2.5\n  );\n\n  scene.add(violetDecision);\n\n  const assets =\n    await loadHardwareAssets();\n\n  const modules =\n    new Map();\n\n  for (const node of NODES) {\n    const built =\n      createModule(\n        node,\n        assets\n      );\n\n    scene.add(built.group);\n    modules.set(\n      node.id,\n      built\n    );\n  }\n\n  const byId =\n    new Map(\n      NODES.map(\n        node => [\n          node.id,\n          node\n        ]\n      )\n    );\n\n  const routes = [];\n\n  for (\n    const [from, to, color]\n    of ROUTES\n  ) {\n    const source =\n      byId.get(from);\n\n    const target =\n      byId.get(to);\n\n    if (!source || !target) {\n      continue;\n    }\n\n    const route =\n      createRoute(\n        source.pos,\n        target.pos,\n        color\n      );\n\n    scene.add(route.group);\n    routes.push(route);\n  }\n\n  const bounds =\n    buildFitBounds(\n      scene,\n      modules\n    );\n\n  const fitCenter =\n    new THREE.Vector3();\n\n  bounds.getCenter(fitCenter);\n\n  const corners =\n    boxCorners(bounds);\n\n  const homeDirection =\n    new THREE.Vector3(\n      0,\n      0.84,\n      0.54\n    ).normalize();\n\n  const homeCamera =\n    new THREE.Vector3();\n\n  const homeTarget =\n    new THREE.Vector3();\n\n  let homeDistance = 18;\n\n  function updateProjection() {\n    const width =\n      Math.max(\n        1,\n        mount.clientWidth\n      );\n\n    const height =\n      Math.max(\n        1,\n        mount.clientHeight\n      );\n\n    const aspect =\n      width / height;\n\n    camera.aspect = aspect;\n\n    camera.fov =\n      aspect < 0.82\n        ? 42\n        : aspect < 1.10\n          ? 39\n          : 36;\n\n    camera.updateProjectionMatrix();\n\n    return {\n      width,\n      height,\n      aspect\n    };\n  }\n\n  function fitsAt(\n    distance,\n    xLimit,\n    yLimit\n  ) {\n    camera.position\n      .copy(fitCenter)\n      .addScaledVector(\n        homeDirection,\n        distance\n      );\n\n    camera.lookAt(fitCenter);\n    camera.updateMatrixWorld(true);\n    camera.updateProjectionMatrix();\n\n    for (const corner of corners) {\n      const projected =\n        corner.clone()\n          .project(camera);\n\n      if (\n        !Number.isFinite(projected.x)\n        || !Number.isFinite(projected.y)\n        || Math.abs(projected.x) > xLimit\n        || Math.abs(projected.y) > yLimit\n      ) {\n        return false;\n      }\n    }\n\n    return true;\n  }\n\n  function computeHomeView() {\n    const {\n      width,\n      height,\n      aspect\n    } = updateProjection();\n\n    renderer.setSize(\n      width,\n      height,\n      false\n    );\n\n    composer.setSize(\n      width,\n      height\n    );\n\n    const xLimit =\n      aspect < 0.82\n        ? 0.92\n        : 0.93;\n\n    const yLimit =\n      aspect < 0.82\n        ? 0.90\n        : 0.92;\n\n    let low = 4;\n    let high = 60;\n\n    for (\n      let index = 0;\n      index < 34;\n      index++\n    ) {\n      const mid =\n        (low + high) / 2;\n\n      if (\n        fitsAt(\n          mid,\n          xLimit,\n          yLimit\n        )\n      ) {\n        high = mid;\n      } else {\n        low = mid;\n      }\n    }\n\n    homeDistance = high;\n\n    homeTarget.copy(fitCenter);\n\n    homeCamera\n      .copy(fitCenter)\n      .addScaledVector(\n        homeDirection,\n        homeDistance\n      );\n\n    controls.minDistance =\n      Math.max(\n        3.5,\n        homeDistance * 0.26\n      );\n\n    controls.maxDistance =\n      Math.max(\n        38,\n        homeDistance * 2.5\n      );\n  }\n\n  function resetView() {\n    computeHomeView();\n\n    camera.position.copy(\n      homeCamera\n    );\n\n    controls.target.copy(\n      homeTarget\n    );\n\n    controls.update();\n  }\n\n  let atHome = true;\n\n  controls.addEventListener(\n    'start',\n    () => {\n      atHome = false;\n    }\n  );\n\n  const resize =\n    () => {\n      const wasHome = atHome;\n\n      updateProjection();\n\n      const width =\n        Math.max(\n          1,\n          mount.clientWidth\n        );\n\n      const height =\n        Math.max(\n          1,\n          mount.clientHeight\n        );\n\n      renderer.setSize(\n        width,\n        height,\n        false\n      );\n\n      composer.setSize(\n        width,\n        height\n      );\n\n      if (wasHome) {\n        resetView();\n      }\n    };\n\n  const resizeObserver =\n    new ResizeObserver(resize);\n\n  resizeObserver.observe(mount);\n\n  const resetButton =\n    document.getElementById(\n      'resetViewBtn'\n    );\n\n  const resetHandler =\n    () => {\n      atHome = true;\n      resetView();\n    };\n\n  resetButton?.addEventListener(\n    'click',\n    resetHandler\n  );\n\n  resetView();\n\n  const raycaster =\n    new THREE.Raycaster();\n\n  const pointer =\n    new THREE.Vector2();\n\n  const pickMeshes =\n    [...modules.values()]\n      .map(\n        module => module.pickMesh\n      );\n\n  let pointerDown = null;\n\n  renderer.domElement.addEventListener(\n    'pointerdown',\n    event => {\n      pointerDown = {\n        x: event.clientX,\n        y: event.clientY\n      };\n    }\n  );\n\n  renderer.domElement.addEventListener(\n    'pointerup',\n    event => {\n      if (!pointerDown) return;\n\n      const movement =\n        Math.hypot(\n          event.clientX - pointerDown.x,\n          event.clientY - pointerDown.y\n        );\n\n      pointerDown = null;\n\n      if (movement > 8) {\n        return;\n      }\n\n      const rect =\n        renderer.domElement\n          .getBoundingClientRect();\n\n      pointer.x =\n        (\n          (\n            event.clientX\n            - rect.left\n          ) / rect.width\n        ) * 2\n        - 1;\n\n      pointer.y =\n        -(\n          (\n            event.clientY\n            - rect.top\n          ) / rect.height\n        ) * 2\n        + 1;\n\n      raycaster.setFromCamera(\n        pointer,\n        camera\n      );\n\n      const hits =\n        raycaster.intersectObjects(\n          pickMeshes,\n          false\n        );\n\n      const nodeId =\n        hits[0]\n          ?.object\n          ?.userData\n          ?.nodeId;\n\n      if (nodeId) {\n        window.dispatchEvent(\n          new CustomEvent(\n            'memeflow:true3d-select',\n            {\n              detail: {\n                nodeId\n              }\n            }\n          )\n        );\n      }\n    }\n  );\n\n  const clock =\n    new THREE.Clock();\n\n  let frame = 0;\n  let disposed = false;\n\n  function animate() {\n    if (disposed) return;\n\n    frame =\n      requestAnimationFrame(\n        animate\n      );\n\n    const time =\n      clock.getElapsedTime();\n\n    animateRoutes(\n      routes,\n      time\n    );\n\n    const core =\n      modules.get('core');\n\n    const decision =\n      modules.get('decision');\n\n    const execution =\n      modules.get('execution');\n\n    if (core?.rings) {\n      core.rings.rotation.y +=\n        0.0015;\n    }\n\n    if (\n      core?.innerGlow\n        ?.material\n    ) {\n      core.innerGlow\n        .material\n        .opacity =\n          0.073\n          + Math.sin(\n            time * 1.9\n          ) * 0.012;\n    }\n\n    if (\n      decision?.innerGlow\n        ?.material\n    ) {\n      decision.innerGlow\n        .material\n        .opacity =\n          0.020\n          + Math.sin(\n            time * 2.0 + 1.4\n          ) * 0.006;\n    }\n\n    if (\n      execution?.innerGlow\n        ?.material\n    ) {\n      execution.innerGlow\n        .material\n        .opacity =\n          0.026\n          + Math.sin(\n            time * 2.0 + 2.6\n          ) * 0.007;\n    }\n\n    controls.update();\n    composer.render();\n  }\n\n  animate();\n\n  function dispose() {\n    if (disposed) return;\n\n    disposed = true;\n\n    cancelAnimationFrame(frame);\n    resizeObserver.disconnect();\n\n    resetButton\n      ?.removeEventListener(\n        'click',\n        resetHandler\n      );\n\n    controls.dispose();\n\n    scene.traverse(object => {\n      object.geometry\n        ?.dispose\n        ?.();\n\n      if (\n        Array.isArray(\n          object.material\n        )\n      ) {\n        for (\n          const material\n          of object.material\n        ) {\n          material\n            ?.dispose\n            ?.();\n        }\n      } else {\n        object.material\n          ?.dispose\n          ?.();\n      }\n    });\n\n    composer.dispose();\n    renderer.dispose();\n    mount.replaceChildren();\n  }\n\n  return {\n    scene,\n    camera,\n    renderer,\n    composer,\n    controls,\n    modules,\n    routes,\n    resetView,\n    dispose\n  };\n}\n\n/* ===== MEMEFLOW_TRUE_3D_GLB_V5 ===== */\n",
    "memeflow-3d/embed.js": "\nimport {\n  bootMemeflowTrue3D\n} from './scene.js?v=true-3d-glb-v5';\n\nasync function startTrue3D() {\n  const viewport =\n    document.querySelector(\n      '.viewport-wrap'\n    );\n\n  if (!viewport) {\n    console.error(\n      '[TRUE-3D] viewport-wrap not found'\n    );\n    return;\n  }\n\n  let host =\n    document.getElementById(\n      'memeflowTrue3DHost'\n    );\n\n  if (!host) {\n    host =\n      document.createElement(\n        'div'\n      );\n\n    host.id =\n      'memeflowTrue3DHost';\n\n    viewport.appendChild(host);\n  }\n\n  window.__MEMEFLOW_TRUE_3D_ACTIVE__ =\n    true;\n\n  requestAnimationFrame(\n    async () => {\n      try {\n        const previous =\n          window.__memeflowTrue3D;\n\n        if (\n          previous\n          && typeof previous.dispose === 'function'\n        ) {\n          previous.dispose();\n        }\n\n        window.__memeflowTrue3D =\n          await bootMemeflowTrue3D(\n            'memeflowTrue3DHost'\n          );\n\n        document\n          .getElementById(\n            'systemCanvas'\n          )\n          ?.setAttribute(\n            'aria-hidden',\n            'true'\n          );\n\n        console.log(\n          '[TRUE-3D] GLB V5 mounted'\n        );\n      }\n\n      catch (error) {\n        window.__MEMEFLOW_TRUE_3D_ACTIVE__ =\n          false;\n\n        console.error(\n          '[TRUE-3D] GLB V5 boot failed',\n          error\n        );\n      }\n    }\n  );\n}\n\nif (\n  document.readyState\n  === 'loading'\n) {\n  document.addEventListener(\n    'DOMContentLoaded',\n    startTrue3D,\n    {\n      once: true\n    }\n  );\n}\n\nelse {\n  startTrue3D();\n}\n",
}

def log(message: str) -> None:
    print(f"[TRUE-3D-GLB-V5] {message}", flush=True)

def run(*args: str, cwd: Path | None = None, check: bool = True):
    result = subprocess.run(
        list(args),
        cwd=cwd,
        text=True,
        capture_output=True,
    )

    if result.stdout.strip():
        print(result.stdout.rstrip())

    if result.stderr.strip():
        print(result.stderr.rstrip(), file=sys.stderr)

    if check and result.returncode != 0:
        raise RuntimeError(
            f"command failed ({result.returncode}): {' '.join(args)}"
        )

    return result

def find_root() -> Path:
    cwd = Path.cwd()

    candidates = [
        cwd,
        cwd / "memeflow-app",
        cwd.parent / "memeflow-app",
        Path.home() / "workspace",
        Path.home() / "workspace" / "memeflow-app",
        Path("/home/runner/workspace"),
        Path("/home/runner/workspace/memeflow-app"),
        Path("/workspace"),
        Path("/workspace/memeflow-app"),
    ]

    seen = set()

    for candidate in candidates:
        try:
            candidate = candidate.resolve()
        except Exception:
            continue

        if candidate in seen:
            continue

        seen.add(candidate)

        if (
            (candidate / "system.html").is_file()
            and
            (candidate / "memeflow-3d" / "scene.js").is_file()
            and
            (candidate / "memeflow-3d" / "embed.js").is_file()
        ):
            return candidate

    raise RuntimeError("MEMEFLOW project root not found")

def git_root(project_root: Path) -> Path | None:
    result = run(
        "git",
        "rev-parse",
        "--show-toplevel",
        cwd=project_root,
        check=False,
    )

    if result.returncode != 0:
        return None

    value = result.stdout.strip()
    return Path(value).resolve() if value else None

def rel(path: Path, repo: Path) -> str:
    return str(
        path.resolve()
        .relative_to(repo.resolve())
    )

def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Install real GLB hardware assets into the existing MEMEFLOW "
            "true-3D viewport. No CSS layer changes."
        )
    )

    parser.add_argument(
        "--push",
        action="store_true",
        help="commit and push after validation",
    )

    args = parser.parse_args()

    root = find_root()
    html_path = root / "system.html"

    scene_path = root / "memeflow-3d" / "scene.js"

    current_scene = scene_path.read_text(
        encoding="utf-8"
    )

    if PATCH_ID in current_scene:
        log("GLB V5 is already installed.")
        return 0

    if (
        "MEMEFLOW_TRUE_3D_BOUNDS_FIX_V4"
        not in current_scene
    ):
        raise RuntimeError(
            "Bounds Fix V4 baseline not found. "
            "Refusing to stack over an unknown renderer."
        )

    text_targets = [
        root / path
        for path in FILES
    ]

    binary_targets = [
        root / "memeflow-3d" / "assets" / name
        for name in ASSETS_B64
    ]

    repo = git_root(root)
    branch = None
    old_head = None

    if repo is not None:
        branch = run(
            "git",
            "branch",
            "--show-current",
            cwd=repo,
        ).stdout.strip()

        old_head = run(
            "git",
            "rev-parse",
            "HEAD",
            cwd=repo,
        ).stdout.strip()

        log(f"git branch: {branch or '(detached)'}")
        log(f"git HEAD:   {old_head or '(unknown)'}")

        if not branch:
            raise RuntimeError("detached HEAD")

        existing = [
            path
            for path in text_targets + binary_targets + [html_path]
            if path.exists()
        ]

        status = run(
            "git",
            "status",
            "--porcelain",
            "--",
            *[
                rel(path, repo)
                for path in existing
            ],
            cwd=repo,
        ).stdout.strip()

        if status:
            print(status)
            raise RuntimeError(
                "Target 3D files have local changes. "
                "Commit/push them first; nothing changed."
            )

    backup_dir = (
        root
        / ".patch-backups"
        / f"true-3d-glb-v5-{STAMP}"
    )

    backup_dir.mkdir(
        parents=True,
        exist_ok=True,
    )

    backup_paths = [
        path
        for path in text_targets + binary_targets + [html_path]
        if path.exists()
    ]

    for path in backup_paths:
        backup_name = (
            str(path.relative_to(root))
            .replace("/", "__")
        )

        shutil.copy2(
            path,
            backup_dir / backup_name,
        )

    log(f"backup: {backup_dir}")

    created_new = []

    try:
        for rel_path, content in FILES.items():
            path = root / rel_path
            path.parent.mkdir(
                parents=True,
                exist_ok=True,
            )

            if not path.exists():
                created_new.append(path)

            path.write_text(
                content.strip() + "\n",
                encoding="utf-8",
            )

        asset_dir = root / "memeflow-3d" / "assets"
        asset_dir.mkdir(
            parents=True,
            exist_ok=True,
        )

        for name, encoded in ASSETS_B64.items():
            path = asset_dir / name

            if not path.exists():
                created_new.append(path)

            path.write_bytes(
                base64.b64decode(encoded)
            )

        html = html_path.read_text(
            encoding="utf-8"
        )

        html, count = re.subn(
            r'/memeflow-3d/embed\.js\?v=[^"\']+',
            f'/memeflow-3d/embed.js?v={VERSION}',
            html,
            count=1,
        )

        if count != 1:
            raise RuntimeError(
                "system.html embed cache-bust anchor not found"
            )

        html_path.write_text(
            html,
            encoding="utf-8",
        )

        for rel_path in FILES:
            path = root / rel_path

            result = run(
                "node",
                "--check",
                str(path),
                check=False,
            )

            if result.returncode != 0:
                raise RuntimeError(
                    f"node --check failed: {path}"
                )

        for path in binary_targets:
            data = path.read_bytes()

            if (
                len(data) < 1000
                or data[:4] != b"glTF"
            ):
                raise RuntimeError(
                    f"invalid GLB asset: {path}"
                )

        final_scene = scene_path.read_text(
            encoding="utf-8"
        )

        checks = [
            PATCH_ID,
            "loadHardwareAssets",
            "await loadHardwareAssets()",
            "0.92",
            "0.90",
            "GLB_CHASSIS_",
        ]

        combined = "\n".join(
            (root / rel_path).read_text(
                encoding="utf-8"
            )
            for rel_path in FILES
        )

        for needle in checks:
            if needle not in (
                final_scene + "\n" + combined
            ):
                raise RuntimeError(
                    f"validation failed: {needle}"
                )

        if repo is not None:
            diff_targets = (
                text_targets
                + binary_targets
                + [html_path]
            )

            run(
                "git",
                "diff",
                "--check",
                "--",
                *[
                    rel(path, repo)
                    for path in diff_targets
                ],
                cwd=repo,
            )

        log("VALIDATION PASS")
        log("TRUE GLB HARDWARE ASSETS installed")
        log("3 chassis variants: standard / core / terminal")
        log("Existing V4 world-bounds safety retained")
        log("Initial composition enlarged while still fit-safe")
        log("Camera angle lowered slightly to show real hardware thickness")
        log("Bloom reduced again for cleaner premium lighting")
        log("Routes moved under hardware with physical endpoint ports")
        log("NO CSS changed; Clean V3 canonical style ownership remains untouched")
        log("Orbit / pinch / Reset View preserved")
        log("Server / AI / telemetry / trading logic untouched")

    except Exception:
        log("Validation failed; restoring exact backup.")

        for path in text_targets + binary_targets + [html_path]:
            backup_name = (
                str(path.relative_to(root))
                .replace("/", "__")
            )

            backup = backup_dir / backup_name

            if backup.exists():
                path.parent.mkdir(
                    parents=True,
                    exist_ok=True,
                )
                shutil.copy2(
                    backup,
                    path,
                )
            elif path in created_new and path.exists():
                path.unlink()

        log("ROLLBACK COMPLETE")
        raise

    if args.push:
        if repo is None or not branch:
            log(
                "--push requested but git worktree is unavailable."
            )
            return 0

        rel_targets = [
            rel(path, repo)
            for path in (
                text_targets
                + binary_targets
                + [html_path]
            )
        ]

        run(
            "git",
            "add",
            "--",
            *rel_targets,
            cwd=repo,
        )

        run(
            "git",
            "diff",
            "--cached",
            "--check",
            cwd=repo,
        )

        staged = run(
            "git",
            "diff",
            "--cached",
            "--quiet",
            cwd=repo,
            check=False,
        )

        if staged.returncode == 0:
            log("No staged changes; nothing to commit.")
            return 0

        commit = run(
            "git",
            "commit",
            "-m",
            "Install true GLB hardware for MEMEFLOW 3D",
            cwd=repo,
            check=False,
        )

        if commit.returncode != 0:
            log(
                "WARNING: V5 installed but commit failed."
            )
            return 0

        push = run(
            "git",
            "push",
            "-u",
            "origin",
            branch,
            cwd=repo,
            check=False,
        )

        if push.returncode != 0:
            log(
                "WARNING: commit created but push failed."
            )
            return 0

        new_head = run(
            "git",
            "rev-parse",
            "HEAD",
            cwd=repo,
        ).stdout.strip()

        log("COMMIT + PUSH COMPLETE")
        log(f"branch: {branch}")
        log(f"previous HEAD: {old_head}")
        log(f"new HEAD:      {new_head}")

    else:
        log(
            "Patch applied locally. "
            "Re-run with --push to commit + push."
        )

    log("DONE")
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(
            f"[TRUE-3D-GLB-V5] ERROR: {exc}",
            file=sys.stderr,
        )
        raise SystemExit(1)
